const weaponDefs=[
 {name:'FÉNIX AR-7',type:'ASALTO · RARO',damage:24,rate:170,mag:30,reserve:180,color:0xc8ff43,icon:'⌁'},
 {name:'MARTILLO M-12',type:'ESCOPETA · ÉPICA',damage:72,rate:720,mag:8,reserve:48,color:0xffa53c,icon:'▰'},
 {name:'VÉRTICE',type:'RIFLE · SECRETA',damage:58,rate:520,mag:12,reserve:48,color:0x42c8ee,icon:'⌖',secret:true},
 {name:'ECLIPSE L',type:'L-CORE · SECRETA',damage:130,rate:1100,mag:5,reserve:25,color:0xa367ff,icon:'◈',secret:true}
];
let player, playerMesh, weaponMesh, bots=[], pickups=[], builds=[], clues=[], particles=[];
let active=false,over=false,hp=100,shield=50,wood=120,stone=80,ammo=30,reserve=180,weapon=0,kills=0,matchTime=0,lastShot=0,reloading=false,reloadEnd=0,lastAI=0,round=1;
let yaw=0,pitch=-.12,keys={},mouseDown=false,moveX=0,moveZ=0,elapsed=0,matchStart=0,zoneRadius=112,stormDuration=240,stormStart=45,playerGround=0,velocityY=0;
const clock=new THREE.Clock(),raycaster=new THREE.Raycaster();
const playerMat=mat(0xe4c948,.6),enemyMat=mat(0xd94e5f),enemyDark=mat(0x592c3b),lootMat=mat(0xd5ff60,.35,0x8dbd2d);
function makeFighter(isPlayer=false){const g=new THREE.Group();const body=new THREE.Mesh(new THREE.CapsuleGeometry(.55,.75,4,8),isPlayer?playerMat:enemyMat);body.position.y=1.05;body.castShadow=true;g.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.31,10,8),mat(isPlayer?0xf0c6a0:0xc88972));head.position.y=1.9;head.castShadow=true;g.add(head);const vest=box(g,0,1.05,0,.95,.5,.68,isPlayer?mat(0x4f706b):enemyDark);vest.position.y=1.12;const pack=box(g,0,1.35,-.4,.48,.62,.22,mat(isPlayer?0x2d4645:0x3c2431));return g}
function makePlayer(){player={x:0,z:0};playerMesh=makeFighter(true);scene.add(playerMesh);weaponMesh=box(playerMesh,.52,1.32,-.35,.17,.16,1.15,mats.metal);weaponMesh.rotation.x=-.04;}
function makeBot(i){let a=Math.random()*Math.PI*2,r=35+Math.random()*65,x=Math.cos(a)*r,z=Math.sin(a)*r;const mesh=makeFighter();mesh.position.set(x,0,z);scene.add(mesh);const gun=box(mesh,.52,1.3,-.25,.14,.15,.85,mat(0x393e3d));bots.push({mesh,x,z,hp:100,attackAt:0,speed:1.6+Math.random()*1.1,phase:Math.random()*6,gun,alive:true,name:['NEBULA','KRAIT','SOMBRA','MORSA','VEX','NÓMADE','HALCÓN','BRUMA','FANTASMA','NIX','REX'][i]||'ECO'})}
function addPickup(x,z,type='ammo',data={}){const g=new THREE.Group();g.position.set(x,.85,z);const core=new THREE.Mesh(new THREE.OctahedronGeometry(.55),type==='secret'?(data.color||mats.purple):type==='heal'?mats.blue:lootMat);core.castShadow=true;g.add(core);const halo=new THREE.Mesh(new THREE.TorusGeometry(.8,.055,6,24),new THREE.MeshBasicMaterial({color:type==='secret'?0xa367ff:0xc8ff43}));halo.rotation.x=Math.PI/2;g.add(halo);scene.add(g);pickups.push({mesh:g,type,data,x,z,baseY:.85})}
function spawnLoot(){for(let i=0;i<16;i++){let x=(Math.random()-.5)*140,z=(Math.random()-.5)*140;addPickup(x,z,i%5===0?'heal':'ammo')}addPickup(17,-28,'secret',{name:'VÉRTICE · RIFLE DE FASE',index:2,color:mats.blue});addPickup(-3,-57,'secret',{name:'ECLIPSE L · ARMA PROHIBIDA',index:3,color:mats.purple});addPickup(-48,3,'secret',{name:'AGUJERO CERO · CAÑÓN SECRETO',index:4,color:mats.orange});
// Four forensic echoes advance the island mystery.
for(const [x,z,title] of [[-34,-28,'ECO 01: NO FUE UNA EVACUACIÓN'],[17,-28,'ECO 02: EL ANILLO ES ARTIFICIAL'],[-3,-57,'ECO 03: SUJETO L-09'],[31,35,'ECO 04: EL ÚLTIMO ECO']]){addPickup(x+2,z+2,'clue',{title})}}
function resetGame(){for(const b of bots)scene.remove(b.mesh);for(const p of pickups)scene.remove(p.mesh);for(const o of builds)scene.remove(o);bots=[];pickups=[];builds=[];kills=0;hp=100;shield=50;wood=120;stone=80;ammo=30;reserve=180;weapon=0;matchTime=0;zoneRadius=112;over=false;reloading=false;yaw=0;pitch=-.12;keys={};$('#endmodal').classList.remove('show');if(playerMesh)scene.remove(playerMesh);makePlayer();for(let i=0;i<11;i++)makeBot(i);spawnLoot();updateHUD();}
makePlayer();
function setWeapon(i){if(i===4){weapon=4;return}weapon=Math.max(0,Math.min(3,i));const d=weaponDefs[weapon];ammo=d.mag;reserve=d.reserve;weaponMesh.material=new THREE.MeshStandardMaterial({color:d.color,metalness:.45,roughness:.36,emissive:d.color,emissiveIntensity:.13});weaponMesh.scale.z=weapon===1?1.2:1;updateHUD()}
function startGame(){resetGame();active=true;over=false;$('#menu').classList.add('hidden');$('#endmodal').classList.remove('show');if(innerWidth>700)canvas.requestPointerLock?.();toast('DESPLIEGUE CONFIRMADO');matchStart=performance.now();clock.getDelta()}
$('#start').addEventListener('click',startGame);$('#restart').addEventListener('click',startGame);$('#closemystery').addEventListener('click',()=>$('#mysterymodal').classList.remove('show'));
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==canvas&&active&&!over)keys={}});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&active){yaw-=e.movementX*.0022;pitch=Math.max(-.55,Math.min(.38,pitch-e.movementY*.0018))}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!active)return;if(e.code==='Digit1')setWeapon(0);if(e.code==='Digit2')setWeapon(1);if(e.code==='Digit3')setWeapon(2);if(e.code==='Digit4')setWeapon(3);if(e.code==='KeyR')reload();if(e.code==='KeyF')build('wall');if(e.code==='KeyG')build('ramp');if(e.code==='KeyE')interact()});document.addEventListener('keyup',e=>keys[e.code]=false);
document.addEventListener('mousedown',e=>{if(e.button===0){mouseDown=true;if(active&&document.pointerLockElement!==canvas&&innerWidth>700)canvas.requestPointerLock?.()}});document.addEventListener('mouseup',e=>{if(e.button===0)mouseDown=false});
let stickOrigin=null;const stick=$('#stick'),nub=$('#nub');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);stickOrigin={x:e.clientX,y:e.clientY};moveX=moveZ=0});stick.addEventListener('pointermove',e=>{if(!stickOrigin)return;let dx=e.clientX-stickOrigin.x,dy=e.clientY-stickOrigin.y,l=Math.hypot(dx,dy),k=Math.min(1,45/(l||1));moveX=dx/45*k;moveZ=dy/45*k;nub.style.transform=`translate(${moveX*33}px,${moveZ*33}px)`});for(const ev of ['pointerup','pointercancel'])stick.addEventListener(ev,()=>{stickOrigin=null;moveX=moveZ=0;nub.style.transform=''});
$('#touchfire').addEventListener('pointerdown',()=>mouseDown=true);$('#touchfire').addEventListener('pointerup',()=>mouseDown=false);$('#touchbuild').onclick=()=>build('wall');$('#touchjump').onclick=()=>{if(playerGround===0)velocityY=8};$('#touchswap').onclick=()=>setWeapon((weapon+1)%4);

