 function makeBot(i){let a=Math.random()*Math.PI*2,r=35+Math.random()*65,x=Math.cos(a)*r,z=Math.sin(a)*r;const mesh=makeFighter();mesh.position.set(x,0,z);scene.add(mesh);box(mesh,.52,1.3,-.25,.14,.15,.85,mat(0x393e3d));bots.push({mesh,x,z,hp:100,attackAt:0,speed:1.6+Math.random()*1.1,phase:Math.random()*6,alive:true,name:['NEBULA','KRAIT','SOMBRA','MORSA','VEX','NÓMADE','HALCÓN','BRUMA','FANTASMA','NIX','REX'][i]||'ECO'})}
 function addPickup(x,z,type='ammo',data={}){const g=new THREE.Group();g.position.set(x,.85,z);const color=type==='secret'?data.color:type==='heal'?mats.blue:type==='clue'?mats.purple:mats.lime;const core=new THREE.Mesh(new THREE.OctahedronGeometry(.55),color);core.castShadow=true;g.add(core);const halo=new THREE.Mesh(new THREE.TorusGeometry(.8,.055,6,24),new THREE.MeshBasicMaterial({color:type==='secret'?0xa367ff:type==='clue'?0xeacaff:0xc8ff43}));halo.rotation.x=Math.PI/2;g.add(halo);scene.add(g);pickups.push({mesh:g,type,data,x,z,baseY:.85})}
 function spawnLoot(){for(let i=0;i<16;i++){let x=(Math.random()-.5)*140,z=(Math.random()-.5)*140;addPickup(x,z,i%5===0?'heal':'ammo')}addPickup(17,-28,'secret',{name:'VÉRTICE · RIFLE DE FASE',index:2,color:mats.blue});addPickup(-3,-57,'secret',{name:'ECLIPSE L · ARMA PROHIBIDA',index:3,color:mats.purple});addPickup(-48,3,'secret',{name:'AGUJERO CERO · CAÑÓN SECRETO',index:4,color:mats.orange});for(const [x,z,title] of [[-34,-28,'ECO 01: NO FUE UNA EVACUACIÓN'],[17,-28,'ECO 02: EL ANILLO ES ARTIFICIAL'],[-3,-57,'ECO 03: SUJETO L-09'],[31,35,'ECO 04: EL ÚLTIMO ECO']])addPickup(x+2,z+2,'clue',{title})}
 function resetGame(){for(const b of bots)scene.remove(b.mesh);for(const p of pickups)scene.remove(p.mesh);for(const o of builds)scene.remove(o);bots=[];pickups=[];builds=[];kills=0;hp=100;shield=50;wood=120;stone=80;ammo=30;reserve=180;weapon=0;matchTime=0;zoneRadius=112;over=false;reloading=false;yaw=0;pitch=-.12;keys={};$('#endmodal').classList.remove('show');if(playerMesh)scene.remove(playerMesh);makePlayer();for(let i=0;i<11;i++)makeBot(i);spawnLoot();updateHUD()}
-function setWeapon(i){weapon=Math.max(0,Math.min(3,i));const d=weaponDefs[weapon];ammo=d.mag;reserve=d.reserve;weaponMesh.material=new THREE.MeshStandardMaterial({color:d.color,metalness:.45,roughness:.36,emissive:d.color,emissiveIntensity:.13});weaponMesh.scale.z=weapon===1?1.2:1;updateHUD()}
+function setWeapon(i){weapon=Math.max(0,Math.min(4,i));const d=weaponDefs[weapon];ammo=d.mag;reserve=d.reserve;weaponMesh.material=new THREE.MeshStandardMaterial({color:d.color,metalness:.45,roughness:.36,emissive:d.color,emissiveIntensity:.13});weaponMesh.scale.z=weapon===1?1.2:1;updateHUD()}
 function startGame(){resetGame();active=true;over=false;$('#menu').classList.add('hidden');$('#endmodal').classList.remove('show');if(innerWidth>700)canvas.requestPointerLock?.();toast('DESPLIEGUE CONFIRMADO');clock.getDelta()}
 $('#start').addEventListener('click',startGame);$('#restart').addEventListener('click',startGame);$('#closemystery').addEventListener('click',()=>$('#mysterymodal').classList.remove('show'));
 document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==canvas&&active&&!over)keys={}});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&active){yaw-=e.movementX*.0022;pitch=Math.max(-.55,Math.min(.38,pitch-e.movementY*.0018))}});
 document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!active)return;if(e.code==='Digit1')setWeapon(0);if(e.code==='Digit2')setWeapon(1);if(e.code==='Digit3')setWeapon(2);if(e.code==='Digit4')setWeapon(3);if(e.code==='KeyR')reload();if(e.code==='KeyF')build('wall');if(e.code==='KeyG')build('ramp');if(e.code==='KeyE')interact()});document.addEventListener('keyup',e=>keys[e.code]=false);

