$('#touchfire').addEventListener('pointerdown',()=>mouseDown=true);$('#touchfire').addEventListener('pointerup',()=>mouseDown=false);$('#touchbuild').onclick=()=>build('wall');$('#touchjump').onclick=()=>{if(playerGround===0)velocityY=8};$('#touchswap').onclick=()=>setWeapon((weapon+1)%5);
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function log(text){const f=$('#feed'),d=document.createElement('div');d.textContent=text;f.prepend(d);while(f.children.length>4)f.lastChild.remove();setTimeout(()=>d.remove(),7000)}
function updateHUD(){const alive=bots.filter(b=>b.alive).length+1;$('#count').textContent=alive;$('#round').textContent=String(round).padStart(2,'0');$('#hp-label').textContent=Math.ceil(hp);$('#hpbar').style.width=Math.max(0,hp)+'%';$('#shield-label').textContent=Math.ceil(shield);$('#shieldbar').style.width=Math.max(0,shield)+'%';$('#wood').textContent=wood;$('#stone').textContent=stone;const d=weaponDefs[weapon]||weaponDefs[0];$('#weaponname').textContent=d.name;$('#weapontype').textContent=d.type;$('#ammo').textContent=reloading?'···':ammo;$('#reserve').textContent=reserve;$('#reloadhint').textContent=ammo===0?'R RECARGAR':'';let slots='';for(let i=0;i<5;i++)slots+=`<div class="slot ${i===weapon?'active':''}"><small>${i+1}</small>${weaponDefs[i].icon}</div>`;$('#slots').innerHTML=slots}
function reload(){const d=weaponDefs[weapon];if(reloading||ammo===d.mag||reserve<=0)return;reloading=true;reloadEnd=performance.now()+1200;toast('RECARGANDO')}
function forward(){return new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw))}
function build(kind){if(!active||over)return;const cost=kind==='wall'?10:15;if(wood<cost){toast('MADERA INSUFICIENTE');return}wood-=cost;const f=forward(),x=player.x+f.x*3,z=player.z+f.z*3;const material=new THREE.MeshStandardMaterial({color:0x9b704d,roughness:.8,transparent:true,opacity:.94});const piece=box(scene,x,kind==='wall'?1.5:1,z,kind==='wall'?4:.7,kind==='wall'?3:.25,kind==='wall'?.28:4,material);piece.rotation.y=yaw+(kind==='ramp'?Math.PI/2:0);if(kind==='ramp')piece.rotation.x=-.28;builds.push(piece);if(builds.length>36){scene.remove(builds.shift())}updateHUD();toast(kind==='wall'?'MURO CONSTRUIDO':'RAMPA DESPLEGADA')}
function hurt(amount){if(shield>0){const s=Math.min(shield,amount);shield-=s;amount-=s}hp=Math.max(0,hp-amount);updateHUD();if(hp<=0)finish(false)}
function finish(win){if(over)return;over=true;active=false;document.exitPointerLock?.();$('#endeyebrow').textContent=win?'ISLA CONQUISTADA':'SIMULACIÓN FINALIZADA';$('#endtitle').textContent=win?'VICTORIA':'ELIMINADO';$('#endtitle').style.color=win?'var(--lime)':'#ff6570';$('#endtext').innerHTML=win?`Eres el último en pie.<br>El misterio completo sigue oculto hasta una hora de juego real.<br><br>ELIMINACIONES: ${kills} · ECOS: ${cluesFound}/4`:`La isla te venció. Aun así, encontraste ${cluesFound}/4 ecos y eliminaste ${kills} rivales.<br>La próxima vez, construye antes de quedar expuesto.`;$('#endmodal').classList.add('show')}
let cluesFound=0,mysteryShown=false,playSeconds=Number(localStorage.getItem('ataqueL_seconds')||0);const secretUnlockAt=3600;
function interact(){let found=null;for(const p of pickups){if(Math.hypot(p.x-player.x,p.z-player.z)<4){found=p;break}}if(!found){toast('NO HAY NADA CERCA');return}const {type,data}=found;if(type==='ammo'){reserve+=weapon===1?10:24;wood+=5;toast('MUNICIÓN +24 · MADERA +5')}else if(type==='heal'){hp=Math.min(100,hp+30);shield=Math.min(100,shield+10);toast('BOTIQUÍN · +30 VIDA')}else if(type==='clue'){cluesFound++;toast(data.title);log('ARCHIVO RECUPERADO: '+data.title);$('#objective').textContent=`ECOS ${cluesFound}/4`;$('#objsub').textContent=cluesFound===4?'Las piezas encajan. Sobrevive hasta el final.':'Busca señales extrañas en las zonas ocultas.'}else if(type==='secret'){let i=data.index;if(i===4)i=4;weapon=i;ammo=weaponDefs[i].mag;reserve=weaponDefs[i].reserve;setWeapon(i);toast('ARMA SECRETA: '+weaponDefs[i].name);log('ARMA ÉPICA DESBLOQUEADA: '+weaponDefs[i].name)}scene.remove(found.mesh);pickups.splice(pickups.indexOf(found),1);updateHUD()}
function collectNear(){let found=pickups.find(p=>Math.hypot(p.x-player.x,p.z-player.z)<2.7);if(found){const was=pickups.indexOf(found);if(found.type==='ammo'||found.type==='heal'||found.type==='secret'||found.type==='clue'){// Press E is deliberate; only nearby clue/secret prompts.
 if(found.type==='ammo'||found.type==='heal'){$('#hint').innerHTML='<b>E</b> RECOGER SUMINISTROS'}else $('#hint').innerHTML=`<b>E</b> ${found.type==='clue'?'LEER ARCHIVO':'RECOGER ARMA SECRETA'}`
 }}else $('#hint').innerHTML='<b>F</b> MURO RÁPIDO &nbsp; <b>G</b> RAMPA &nbsp; <b>E</b> RECOGER'}
function fire(){if(!active||over)return;if(reloading){return}const d=weaponDefs[weapon],now=performance.now();if(now-lastShot<d.rate)return;if(ammo<=0){reload();return}lastShot=now;ammo--;updateHUD();weaponMesh.position.z=-.6;setTimeout(()=>{if(weaponMesh)weaponMesh.position.z=-.35},65);
const dir=new THREE.Vector3(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch));const origin=new THREE.Vector3(player.x,playerGround+1.55,player.z).addScaledVector(forward(),.8);let target=null,best=2.8;for(const b of bots){if(!b.alive)continue;const pos=new THREE.Vector3(b.x,1.3,b.z),to=pos.clone().sub(origin),dist=to.length();if(dist>60)continue;const angle=dir.angleTo(to.normalize());if(angle<best){best=angle;target=b}}
if(target){let damage=d.damage;if(weapon===1)damage*=Math.max(.45,1-best/2.8);target.hp-=damage;hitFlash(target);if(target.hp<=0){target.alive=false;scene.remove(target.mesh);kills++;wood+=12;log(`ELIMINACIÓN · ${target.name}`);toast(`${target.name} ELIMINADO`);addPickup(target.x,target.z,'ammo');if(bots.every(b=>!b.alive))finish(true)}else log(`IMPACTO · ${target.name} −${Math.ceil(damage)}`)}else muzzle(origin.clone().addScaledVector(dir,8),d.color);}
function hitFlash(b){const s=new THREE.Mesh(new THREE.SphereGeometry(.24,8,6),new THREE.MeshBasicMaterial({color:0xffe57a}));s.position.set(b.x,1.55,b.z);scene.add(s);particles.push({mesh:s,life:.16})}
function muzzle(pos,color){const o=new THREE.Mesh(new THREE.SphereGeometry(.14,6,6),new THREE.MeshBasicMaterial({color}));o.position.copy(pos);scene.add(o);particles.push({mesh:o,life:.09})}
function updatePlayer(dt){const f=forward(),right=new THREE.Vector3(-f.z,0,f.x);let forwardInput=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-moveZ,leftRight=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+moveX;let v=f.multiplyScalar(forwardInput).add(right.multiplyScalar(leftRight));if(v.lengthSq()>1)v.normalize();const speed=(keys.ShiftLeft||keys.ShiftRight?10:6)*dt;player.x=Math.max(-120,Math.min(120,player.x+v.x*speed));player.z=Math.max(-120,Math.min(120,player.z+v.z*speed));if(v.lengthSq()>.01)playerMesh.rotation.y=Math.atan2(-v.x,-v.z);if((keys.Space)&&playerGround===0)velocityY=8;velocityY-=20*dt;playerGround=Math.max(0,playerGround+velocityY*dt);if(playerGround===0)velocityY=0;playerMesh.position.set(player.x,playerGround,player.z);const cx=player.x+Math.sin(yaw)*7,cz=player.z+Math.cos(yaw)*7;camera.position.set(cx,playerGround+3.1,cz);camera.lookAt(player.x,playerGround+1.45,player.z);if(mouseDown)fire();collectNear();if(reloading&&performance.now()>reloadEnd){let n=Math.min(weaponDefs[weapon].mag-ammo,reserve);ammo+=n;reserve-=n;reloading=false;updateHUD()}}

